int main(int argc,const char**argv){@autoreleasepool{try{
 need(argc==2,"report required");id<MTLDevice>d=nil;for(id<MTLDevice>x in MTLCopyAllDevices())if([x.name containsString:@"5600M"])d=x;need(d!=nil,"5600M required");NSMutableArray*sets=[NSMutableArray array];id<MTLCounterSet>timestamp=nil;for(id<MTLCounterSet>s in d.counterSets){[sets addObject:s.name];if([s.name isEqualToString:MTLCommonCounterSetTimestamp])timestamp=s;}
 NSMutableDictionary*report=[@{@"device":d.name,@"counterSets":sets,@"drawSampling":@([d supportsCounterSampling:MTLCounterSamplingPointAtDrawBoundary]),@"dispatchSampling":@([d supportsCounterSampling:MTLCounterSamplingPointAtDispatchBoundary]),@"stageSampling":@([d supportsCounterSampling:MTLCounterSamplingPointAtStageBoundary]),@"GPUOutputVerified":@NO,@"faultPartialReadbackVerified":@NO} mutableCopy];
