  auto lib=[d newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;kernel void cs(device uint*p [[buffer(0)]],uint i [[thread_position_in_grid]]){p[i]=i*3+7;}" options:nil error:&error];auto fn=[lib newFunctionWithName:@"cs"];auto pipeline=[d newComputePipelineStateWithFunction:fn error:&error];need(pipeline!=nil,"pipeline failed");auto values=[d newBufferWithLength:1024 options:MTLResourceStorageModeShared];auto q=[d newCommandQueue];auto cb=[q commandBuffer];NSMutableDictionary*record=[NSMutableDictionary dictionary];mvkBeginGPUTimestamps(record,cb,0);auto ce=[cb computeCommandEncoder];[ce setComputePipelineState:pipeline];[ce setBuffer:values offset:0 atIndex:0];[ce sampleCountersInBuffer:samples atSampleIndex:0 withBarrier:NO];mvkSampleGPUTimestamp(record,ce,@"compute-pipeline",@"known-linear-output");[ce dispatchThreadgroups:MTLSizeMake(4,1,1) threadsPerThreadgroup:MTLSizeMake(64,1,1)];[ce sampleCountersInBuffer:samples atSampleIndex:1 withBarrier:NO];mvkSampleGPUTimestamp(record,ce,@"encoder-end",@"known-linear-output");[ce endEncoding];[cb commit];[cb waitUntilCompleted];need(cb.status==MTLCommandBufferStatusCompleted,"GPU command failed");
  unsigned bad=0;for(unsigned i=0;i<256;++i)if(((uint32_t*)values.contents)[i]!=i*3+7)++bad;NSData*data=[samples resolveCounterRange:NSMakeRange(0,2)];need(data.length==2*sizeof(MTLCounterResultTimestamp),"timestamp resolve failed");auto ts=(const MTLCounterResultTimestamp*)data.bytes;need(ts[0].timestamp!=MTLCounterErrorValue&&ts[1].timestamp!=MTLCounterErrorValue,"counter error value");report[@"timestamps"]=@[@(ts[0].timestamp),@(ts[1].timestamp)];report[@"GPUValuesChecked"]=@256;report[@"mismatches"]=@(bad);report[@"GPUOutputVerified"]=@(!bad);report[@"CPUResolveAfterCompletionWorks"]=@YES;report[@"samplingInsertsFence"]=@NO;record[@"nativeCompleted"]=@YES;NSDictionary*observed=mvkSnapshotGPUTimestamps(record);report[@"nativeTraceHelper"]=observed;need([observed[@"enabled"]boolValue]&&[observed[@"CPUResolveSucceeded"]boolValue]&&[observed[@"samples"]count]==2,"native trace helper not active");for(NSDictionary*r in observed[@"samples"])need([r[@"valid"]boolValue],"native trace counter invalid");mvkEndGPUTimestamps(record);need(mvkGPUTimestampInFlight()==0,"counter budget not released");
  [q release];[values release];[pipeline release];[fn release];[lib release];[samples release];[desc release];
 }
